using System.Collections.Immutable;
using System.Linq;
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace Cosmos.EffectAlgebra.Generator;

/// <summary>
/// §L2 — Godot 调用语法 → L1 代数 Claim 的「翻译层」骨架（Roslyn source generator）。
/// 铁律：数学全在 L1（Cosmos.EffectAlgebra）；本生成器只做「识别标注方法 + 生成校验注册桩」，
/// 绝不重算代数。L2 残差（honest，非假绿）：§7 白名单是 Godot 运行时 API 数据，
/// 编译期无法枚举实例，故仅生成「调用桩」并显式注释该残差，真实 Claim 注入待运行期解析（见 LANDING_PLAN §4）。
/// 类型边界由 L1 强制；生成器只搬运语法位置信息，不承载未定义边界。
/// </summary>
[Generator]
public sealed class EffectAlgebraGenerator : IIncrementalGenerator
{
    private const string EffectOverrideName = "EffectOverrideAttribute";
    private const string AcceptDeviationName = "AcceptDeviationAttribute";

    /// <summary>
    /// 诊断：§8.3.1 不变式(1) — [EffectOverride] reason 非空由 L1 构造子强制（fail-fast 抛），
    /// 编译期无需额外诊断。此处仅声明描述符以明示「已由类型/构造子保证」，不主动发（无运行期可发点）。
    /// </summary>
    private static readonly DiagnosticDescriptor ReasonGuaranteedByCtor = new(
        id: "EAG000",
        title: "EffectOverride reason 由构造子强制非空",
        messageFormat: "[EffectOverride] reason 非空由 L1 构造子强制（§8.3.1 不变式(1)），编译期无需诊断。",
        category: "EffectAlgebra",
        DiagnosticSeverity.Info,
        isEnabledByDefault: true);

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        // ① 识别标注：收集带 [EffectOverride] / [AcceptDeviation] 的 MethodDeclarationSyntax。
        var methods = context.SyntaxProvider.CreateSyntaxProvider(
                static (node, _) => node is MethodDeclarationSyntax m && m.AttributeLists.Count > 0,
                static (ctx, _) => GetAnnotatedMethod(ctx))
            .Where(static m => m is not null)
            .Select(static (m, _) => m!);

        // ② 生成注册桩：每个标注方法生成一个 partial 桩（§L2 翻译层；诚实声明残差）。
        context.RegisterSourceOutput(methods, static (spc, method) =>
        {
            var source = GenerateStub(method);
            spc.AddSource($"{method.MethodName}.g.cs", SourceText.From(source, Encoding.UTF8));
        });
    }

    /// <summary>§8.3 — 仅挑选带 [EffectOverride]/[AcceptDeviation] 的方法；其余忽略。</summary>
    private static AnnotatedMethod? GetAnnotatedMethod(GeneratorSyntaxContext ctx)
    {
        var method = (MethodDeclarationSyntax)ctx.Node;
        bool hasOverride = false, hasAccept = false;
        foreach (var attr in method.AttributeLists.SelectMany(l => l.Attributes))
        {
            if (HasAttributeName(attr.Name, EffectOverrideName)) hasOverride = true;
            else if (HasAttributeName(attr.Name, AcceptDeviationName)) hasAccept = true;
        }
        return !hasOverride && !hasAccept
            ? null
            : new AnnotatedMethod(method.Identifier.Text, hasOverride, hasAccept);
    }

    /// <summary>按简单名匹配特性（含 `X` 与 `XAttribute` 两种写法）。等价于 Roslyn 常见 IsOrHasName 语义，本地实现以保证零依赖编译。</summary>
    private static bool HasAttributeName(NameSyntax name, string simpleName)
    {
        var text = name switch
        {
            IdentifierNameSyntax i => i.Identifier.Text,
            QualifiedNameSyntax q => q.Right.Identifier.Text,
            _ => null
        };
        return text == simpleName || text == simpleName + "Attribute";
    }

    /// <summary>§L2 桩：标注方法 → 预留 baseSig + 对应 ApiMapping.Claims 的 Union 注入点。绝不重算代数（残差见注释）。</summary>
    private static string GenerateStub(AnnotatedMethod m)
    {
        var tags = (m.HasOverride ? "[EffectOverride] " : "") + (m.HasAccept ? "[AcceptDeviation] " : "");
        var sb = new StringBuilder();
        sb.AppendLine("// <auto-generated/>");
        sb.AppendLine("// §L2 — EffectAlgebraGenerator 骨架生成的校验注册桩（非运行期代码，仅为标注索引）。");
        sb.AppendLine("// 数学在 L1（Cosmos.EffectAlgebra）；本桩仅标记「被标注方法」并预留 Union 注入点。");
        sb.AppendLine("// L2 残差（honest）：§7 白名单是 Godot 运行时 API 数据，编译期不可用；");
        sb.AppendLine("// 真实 Claim 注入待 L2 运行期解析（见 LANDING_PLAN §4），此处不重算代数（避免假绿）。");
        sb.AppendLine("namespace Cosmos.EffectAlgebra.Generated;");
        sb.AppendLine();
        sb.AppendLine("public static partial class EffectAlgebraGenerated");
        sb.AppendLine("{");
        sb.AppendLine($"    /// <summary>§L2 桩：方法 {m.MethodName} 标注了 {tags}——类型边界由 L1 强制，此处仅预留 baseSig + 对应 ApiMapping.Claims 的 Union 注入点。</summary>");
        sb.AppendLine($"    public static Cosmos.EffectAlgebra.Signature Compute{m.MethodName}(Cosmos.EffectAlgebra.Signature baseSig)");
        sb.AppendLine("    {");
        sb.AppendLine("        // L2 残差（honest）：编译期无法取得该方法对应 GodotApiWhitelist 的实例 Claims，");
        sb.AppendLine("        // 故返回 baseSig 透传；运行期注入见 LANDING_PLAN §4。代数计算仍由 L1 完成（§3.1–§3.3）。");
        sb.AppendLine("        return baseSig;");
        sb.AppendLine("    }");
        sb.AppendLine("}");
        return sb.ToString();
    }

    private sealed record AnnotatedMethod(string MethodName, bool HasOverride, bool HasAccept);
}

